"use strict";(self.webpackChunkPromoScreen=self.webpackChunkPromoScreen||[]).push([[247],{60247:a=>{a.exports=JSON.parse('{"reviews":{"get_pregnant":[{"id":"gp_1","text":"Wszystko fajnie, przejrzyście 😊 Dzięki tej aplikacji udało mi się śledzić dni płodne i zajść w ciążę za pierwszym razem 😍","userName":"Natalia Pryboda"},{"id":"gp_2","text":"Aplikacja jak dla mnie jest rewelacyjna! Dobrze wylicza miesiączkę, dni płodne – a teraz tygodnie ciąży 😊 Podoba mi się grafika dziecka i informacje na temat poszczególnych tygodni ciąży. Miałam różne aplikacje, ale ta zdecydowanie w moim przypadku jest najlepsza.","userName":"Gosia O"},{"id":"gp_3","text":"Bardzo dokładna aplikacja i najlepsza, jaka jest na rynku. Dzięki niej zaszłam dwa razy w ciążę, bo dokładnie określa dni płodne. Fenomen wśród wszystkich aplikacji.","userName":"KACPER YT"}],"track_cycle":[{"text":"Bardzo dobra aplikacja. Dopiero dzięki jej pomocy zauważyłam, że pewne dolegliwości bólowe związane są z miesiączką. Prosta i szybka w obsłudze. Niezbędnik każdej dziewczyny i kobiety.","userName":"Magdalena Iwa","id":"tc_1"},{"text":"Bardzo pomocna apka, pomaga prześledzić cykl i dobrze wyznaczyć termin miesiączki czy owulacji, mimo że mam PCOS","userName":"Nina Schonthaler","id":"tc_2"},{"text":"Dobra aplikacja, w której poza śledzeniem cyklu i dostępem do wykresów można włączyć krokomierz i przypominanie o nawadnianiu :)","userName":"Paulina Kowalska","id":"tc_3"}],"follow_pregnancy":[{"id":"fp_1","text":"Jestem bardzo zadowolona z aplikacji. Dowiedziałam się wielu rzeczy o różnych dolegliwościach w ciąży, jakie trzeba wykonać badania i co robić, by rozwój dziecka był przeze mnie wspierany.","userName":"Malgorzata Krakowczyk"},{"id":"fp_2","text":"Świetna aplikacja, sprawdzila sie przy planowaniu ciąży, przebiegu i po porodzie aż do dnia dzisiejszego. Nie mam w planach kończyć korzystania :) Polecam!","userName":"N Ol"},{"id":"fp_3","text":"Świetna aplikacja, przeprowadziła mnie przez całą ciążę, po urodzeniu dziecka wciąż jej używam, jest w niej wiele ciekawych, przydatnych artykułów. Polecam!","userName":"Marta Waga"}]}}')}}]);
